window.SCRIPT_ORIGINALS["d3305f05f2882219f57320bcf4ff9d35d6ec510adcff50af5db961b1c427ce10"]={"f":"复活庆典v3.0.json","t":"[{\n\t\t\"id\": \"_meta\",\n\t\t\"logo\": \"https://i.postimg.cc/Vs30P8F4/image.png\",\n\t\t\"name\": \"复活庆典v3.0\",\n\t\t\"townsfolkName\": \"镇民\",\n\t\t\"author\": \"Zets\"\n\t},\n  {\n    \"firstNightReminder\": \"决定失忆者的能力。如果失忆者的能力会让他在今晚醒来：唤醒他并执行其能力。\",\n    \"otherNightReminder\": \"如果失忆者的能力会让他在今晚醒来：唤醒他并执行其能力。\",\n    \"name\": \"失忆者\",\n    \"otherNight\": 5,\n    \"setup\": false,\n    \"reminders\": [\n      \"？\"\n    ],\n    \"id\": \"amnesiacbutton\",\n    \"edition\": \"custom\",\n    \"team\": \"townsfolk\",\n    \"name_eng\": \"Amnesiac\",\n    \"firstNight\": 12,\n    \"ability\": \"你不知道你的能力是什么。每个白天你可以找说书人猜测一次，你会得知你的猜测有多准确。\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/amnesiac.png\"\n  },\n  {\n    \"firstNightReminder\": \"展示那个外来者角色标记。指向被你标记“外来者”和“错误”的两名玩家。\",\n    \"otherNightReminder\": \"\",\n    \"name\": \"图书管理员\",\n    \"otherNight\": 0,\n    \"setup\": false,\n    \"reminders\": [\n      \"外来者\",\n      \"错误\"\n    ],\n    \"id\": \"librarianbutton\",\n    \"edition\": \"custom\",\n    \"team\": \"townsfolk\",\n    \"name_eng\": \"Librarian\",\n    \"firstNight\": 33,\n    \"ability\": \"在你的首个夜晚，你会得知两名玩家和一个外来者角色：这两名玩家之一是该角色（或者你会得知没有外来者在场）。\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/librarian.png\"\n  },\n  {\n    \"firstNightReminder\": \"指向一名邪恶玩家。随后唤醒那名因赏金猎人而转变为邪恶的镇民，并告知他变成了邪恶阵营。\",\n    \"otherNightReminder\": \"如果赏金猎人知晓的邪恶玩家死亡，指向另一名邪恶玩家。\",\n    \"name\": \"赏金猎人\",\n    \"otherNight\": 65,\n    \"setup\": true,\n    \"reminders\": [\n      \"被得知\",\n      \"邪恶\"\n    ],\n    \"id\": \"bounty_hunterbutton\",\n    \"edition\": \"custom\",\n    \"team\": \"townsfolk\",\n    \"name_eng\": \"Bounty Hunter\",\n    \"firstNight\": 45,\n    \"ability\": \"在你的首个夜晚，你会得知一名邪恶玩家。每当你得知的玩家死亡，你会在当晚得知另一名邪恶玩家。[会有一名镇民转变为邪恶阵营]\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/bounty_hunter.png\"\n  },\n  {\n    \"firstNightReminder\": \"对小精灵展示一个在场的镇民角色。\",\n    \"otherNightReminder\": \"\",\n    \"name\": \"小精灵\",\n    \"otherNight\": 0,\n    \"setup\": false,\n    \"reminders\": [\n      \"疯狂\",\n      \"获得能力\"\n    ],\n    \"id\": \"pixiebutton\",\n    \"edition\": \"custom\",\n    \"team\": \"townsfolk\",\n    \"name_eng\": \"Pixie\",\n    \"firstNight\": 29,\n    \"ability\": \"在你的首个夜晚，你会得知一个在场的镇民角色。如果你“疯狂”地证明你是该角色，当他死亡时你获得该角色的能力。\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/pixie.png\"\n  },\n  {\n    \"firstNightReminder\": \"选择一种角色类型，并告知其一个符合该类型的玩家。在该玩家旁边标记已被知晓。\",\n    \"otherNightReminder\": \"选择一种尚未被气球驾驶员知晓的角色类型，并告知其一个符合该类型的玩家。在该玩家旁边标记已被知晓。如果所有类型均已被知晓或无该种类型，气球驾驶员不会醒来。\",\n    \"name\": \"气球驾驶员\",\n    \"otherNight\": 63,\n    \"setup\": true,\n    \"reminders\": [\n      \"得知镇民\",\n      \"得知外来者\",\n      \"得知爪牙\",\n      \"得知恶魔\",\n      \"得知旅行者\"\n    ],\n    \"id\": \"balloonistbutton\",\n    \"edition\": \"custom\",\n    \"team\": \"townsfolk\",\n    \"name_eng\": \"Balloonist\",\n    \"firstNight\": 44,\n    \"ability\": \"每个夜晚，你会得知一名不同角色类型的玩家，直到场上所有的角色类型你都得知过一次。[+1 外来者]\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/balloonist.png\"\n  },\n  {\n    \"firstNightReminder\": \"\",\n    \"otherNightReminder\": \"\",\n    \"name\": \"博学者\",\n    \"otherNight\": 0,\n    \"setup\": false,\n    \"reminders\": [],\n    \"id\": \"savantbutton\",\n    \"edition\": \"custom\",\n    \"team\": \"townsfolk\",\n    \"name_eng\": \"Savant\",\n    \"firstNight\": 0,\n    \"ability\": \"每个白天，你可以私下询问说书人以得知两条信息：一个是正确的，一个是错误的。\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/savant.png\"\n  },\n  {\n    \"firstNightReminder\": \"守夜人可以指向一名玩家。如果他这么做，则唤醒那名玩家，告知其被守夜人选中，且告知他守夜人是谁。\",\n    \"otherNightReminder\": \"守夜人可以指向一名玩家。如果他这么做，则唤醒那名玩家，告知其被守夜人选中，且告知他守夜人是谁。\",\n    \"name\": \"守夜人\",\n    \"otherNight\": 66,\n    \"setup\": false,\n    \"reminders\": [\n      \"失去能力\"\n    ],\n    \"id\": \"nightwatchmanbutton\",\n    \"edition\": \"custom\",\n    \"team\": \"townsfolk\",\n    \"name_eng\": \"Nightwatchman\",\n    \"firstNight\": 46,\n    \"ability\": \"每局游戏限一次，在夜晚时，你可以选择一名玩家：他会得知你是守夜人。\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/nightwatchman.png\"\n  },\n  {\n    \"firstNightReminder\": \"巡山人选择不使用能力，或指向一名玩家。如果他指向了落难少女，则为落难少女安排一个新的不在场镇民角色，将其唤醒并告知她新的角色。\",\n    \"otherNightReminder\": \"巡山人选择不使用能力，或指向一名玩家。如果他指向了落难少女，则为落难少女安排一个新的不在场镇民角色，将其唤醒并告知她新的角色。\",\n    \"name\": \"巡山人\",\n    \"otherNight\": 51,\n    \"setup\": true,\n    \"reminders\": [\n      \"失去能力\"\n    ],\n    \"id\": \"huntsmanbutton\",\n    \"edition\": \"custom\",\n    \"team\": \"townsfolk\",\n    \"name_eng\": \"Huntsman\",\n    \"firstNight\": 30,\n    \"ability\": \"每局游戏限一次，在夜晚时，你可以选择一名存活的玩家：如果你选中了落难少女，她会变成一个不在场的镇民角色。[+落难少女]\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/huntsman.png\"\n  },\n  {\n    \"firstNightReminder\": \"\",\n    \"otherNightReminder\": \"\",\n    \"name\": \"渔夫\",\n    \"otherNight\": 0,\n    \"setup\": false,\n    \"reminders\": [\n      \"失去能力\"\n    ],\n    \"id\": \"fishermanbutton\",\n    \"edition\": \"custom\",\n    \"team\": \"townsfolk\",\n    \"name_eng\": \"Fisherman\",\n    \"firstNight\": 0,\n    \"ability\": \"每局游戏限一次，在白天时，你可以让说书⼈给你一些能帮助你的阵营获胜的建议。\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/fisherman.png\"\n  },\n  {\n    \"firstNightReminder\": \"\",\n    \"otherNightReminder\": \"如果农民在夜晚死去，则选择另一位善良玩家成为农民。唤醒这名玩家，并告知他成为了农民。\",\n    \"name\": \"农夫\",\n    \"otherNight\": 46,\n    \"setup\": false,\n    \"reminders\": [],\n    \"id\": \"farmerbutton\",\n    \"edition\": \"custom\",\n    \"team\": \"townsfolk\",\n    \"name_eng\": \"Farmer\",\n    \"firstNight\": 0,\n    \"ability\": \"如果你在夜晚死亡，一名存活的善良玩家会变成农夫。\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/farmer.png\"\n  },\n  {\n    \"firstNightReminder\": \"\",\n    \"otherNightReminder\": \"\",\n    \"name\": \"贞洁者\",\n    \"otherNight\": 0,\n    \"setup\": false,\n    \"reminders\": [\n      \"失去能力\"\n    ],\n    \"id\": \"virginbutton\",\n    \"edition\": \"custom\",\n    \"team\": \"townsfolk\",\n    \"name_eng\": \"Virgin\",\n    \"firstNight\": 0,\n    \"ability\": \"当你首次被提名时，如果提名你的玩家是镇民，他立刻被处决。\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/virgin.png\"\n  },\n  {\n    \"firstNightReminder\": \"如果异教徒和异端分子都在场，唤醒所有善良的镇民，并告知他们都成为了异教徒。\",\n    \"otherNightReminder\": \"\",\n    \"name\": \"异教徒\",\n    \"otherNight\": 0,\n    \"setup\": true,\n    \"reminders\": [],\n    \"id\": \"pagan\",\n    \"edition\": \"custom\",\n    \"team\": \"townsfolk\",\n    \"name_eng\": \"Pagan\",\n    \"firstNight\": 26,\n    \"ability\": \"如果异端分子在场，所有其他善良镇民变为异教徒，并且得知邪恶玩家是谁及他们的角色。[+异端分子或-1外来者]\",\n    \"image\": \"https://www.bloodstar.xyz/p/Airell_clocktower/Assets_of_Lei_Gallery/pagan_assets_of_lei_gallery.png\"\n  },\n  {\n    \"firstNightReminder\": \"\",\n    \"otherNightReminder\": \"\",\n    \"name\": \"食人族\",\n    \"otherNight\": 0,\n    \"setup\": false,\n    \"reminders\": [\n      \"中毒\",\n      \"死于处决\"\n    ],\n    \"id\": \"cannibalbutton\",\n    \"edition\": \"custom\",\n    \"team\": \"townsfolk\",\n    \"name_eng\": \"Cannibal\",\n    \"firstNight\": 0,\n    \"ability\": \"你拥有上个死于处决的玩家的能力。如果该玩家属于邪恶阵营，你中毒直到下个善良玩家死于处决。\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/cannibal.png\"\n  },\n  {\n    \"firstNightReminder\": \"\",\n    \"otherNightReminder\": \"\",\n    \"name\": \"畸形秀演员\",\n    \"otherNight\": 0,\n    \"setup\": false,\n    \"reminders\": [],\n    \"id\": \"mutantbutton\",\n    \"edition\": \"custom\",\n    \"team\": \"outsider\",\n    \"name_eng\": \"Mutant\",\n    \"firstNight\": 0,\n    \"ability\": \"如果你“疯狂”地证明自己是外来者，你可能被处决。\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/mutant.png\"\n  },\n  {\n    \"firstNightReminder\": \"唤醒所有爪牙，并告知他们场中有落难少女。\",\n    \"otherNightReminder\": \"如果被巡山人选中，唤醒并为其展示新角色。\",\n    \"name\": \"落难少女\",\n    \"otherNight\": 52,\n    \"setup\": false,\n    \"reminders\": [\n      \"已被猜测\"\n    ],\n    \"id\": \"damselbutton\",\n    \"edition\": \"custom\",\n    \"team\": \"outsider\",\n    \"name_eng\": \"Damsel\",\n    \"firstNight\": 31,\n    \"ability\": \"所有爪牙都知道落难少女在场。每局游戏限一次，任意爪牙可以公开猜测你是落难少女，如果猜对，你的阵营落败。\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/damsel.png\"\n  },\n  {\n    \"firstNightReminder\": \"\",\n    \"otherNightReminder\": \"\",\n    \"name\": \"酒鬼\",\n    \"otherNight\": 0,\n    \"setup\": true,\n    \"reminders\": [],\n    \"id\": \"drunkbutton\",\n    \"edition\": \"custom\",\n    \"remindersGlobal\": [\n      \"是酒鬼\"\n    ],\n    \"team\": \"outsider\",\n    \"name_eng\": \"Drunk\",\n    \"firstNight\": 0,\n    \"ability\": \"你不知道你是酒鬼。你以为你是一个镇民角色，但其实你不是。\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/drunk.png\"\n  },\n  {\n    \"firstNightReminder\": \"如果有七名或更多玩家，唤醒疯子：展示“他们是你的爪牙”信息标记。指向任意对应数量的玩家。展示“这些角色不在场”信息标记。展示三个善良角色。让疯子重新入睡。唤醒恶魔。展示“你是”信息标记和恶魔角色标记。展示“这名玩家是”信息标记和疯子角色标记，然后指向疯子玩家。\",\n    \"otherNightReminder\": \"做任何需要做的事情来模拟一位恶魔的行动。让疯子重新入睡。唤醒恶魔。对恶魔展示疯子角色标记，并指向疯子玩家，随后是疯子的攻击目标。\",\n    \"name\": \"疯子\",\n    \"otherNight\": 21,\n    \"setup\": false,\n    \"reminders\": [],\n    \"id\": \"lunaticbutton\",\n    \"edition\": \"custom\",\n    \"remindersGlobal\": [\n      \"是疯子\",\n      \"被选择\"\n    ],\n    \"team\": \"outsider\",\n    \"name_eng\": \"Lunatic\",\n    \"firstNight\": 7,\n    \"ability\": \"你以为你是一个恶魔，但其实你不是。恶魔知道你是疯子以及你在每个夜晚选择了哪些玩家。\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/lunatic.png\"\n  },\n  {\n    \"firstNightReminder\": \"\",\n    \"otherNightReminder\": \"\",\n    \"name\": \"异端分子\",\n    \"otherNight\": 0,\n    \"setup\": false,\n    \"reminders\": [],\n    \"id\": \"hereticbutton\",\n    \"edition\": \"custom\",\n    \"team\": \"outsider\",\n    \"name_eng\": \"Heretic\",\n    \"firstNight\": 0,\n    \"ability\": \"对调胜负结果，即使你已死亡。\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/heretic.png\"\n  },\n  {\n    \"firstNightReminder\": \"选择一个邻近恶魔的善良玩家放置提线木偶标记。唤醒恶魔并告知他谁是提线木偶。\",\n    \"otherNightReminder\": \"\",\n    \"name\": \"提线木偶\",\n    \"otherNight\": 0,\n    \"setup\": true,\n    \"reminders\": [],\n    \"id\": \"marionettebutton\",\n    \"edition\": \"custom\",\n    \"remindersGlobal\": [\n      \"是提线木偶\"\n    ],\n    \"team\": \"minion\",\n    \"name_eng\": \"Marionette\",\n    \"firstNight\": 11,\n    \"ability\": \"你以为你是一个善良角色，但其实你不是。恶魔会知道你是提线木偶。[提线木偶会与恶魔邻座]\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/marionette.png\"\n  },\n  {\n    \"firstNightReminder\": \"\",\n    \"otherNightReminder\": \"\",\n    \"name\": \"男爵\",\n    \"otherNight\": 0,\n    \"setup\": true,\n    \"reminders\": [],\n    \"id\": \"baronbutton\",\n    \"edition\": \"custom\",\n    \"team\": \"minion\",\n    \"name_eng\": \"Baron\",\n    \"firstNight\": 0,\n    \"ability\": \"会有额外的外来者在场。[+2 外来者]\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/baron.png\"\n  },\n  {\n    \"firstNightReminder\": \"让洗脑师选择一名玩家和一个善良角色。标记那名玩家疯狂。让洗脑师重新入睡。唤醒洗脑师的目标。对这名玩家展示“该角色的能力对你生效”信息标记，洗脑师角色标记，该玩家需要疯狂证明的角色标记。\",\n    \"otherNightReminder\": \"让洗脑师选择一名玩家和一个善良角色。标记那名玩家疯狂。让洗脑师重新入睡。唤醒洗脑师的目标。对这名玩家展示“该角色的能力对你生效”信息标记，洗脑师角色标记，该玩家需要疯狂证明的角色标记。\",\n    \"name\": \"洗脑师\",\n    \"otherNight\": 16,\n    \"setup\": false,\n    \"reminders\": [\n      \"疯狂\"\n    ],\n    \"id\": \"cerenovusbutton\",\n    \"edition\": \"custom\",\n    \"team\": \"minion\",\n    \"name_eng\": \"Cerenovus\",\n    \"firstNight\": 25,\n    \"ability\": \"每个夜晚，你要选择一名玩家和一个善良角色。他明天白天和夜晚需要“疯狂”地证明自己是这个角色，不然他可能被处决。\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/cerenovus.png\"\n  },\n  {\n    \"firstNightReminder\": \"\",\n    \"otherNightReminder\": \"如果红唇女郎今天变成了小恶魔，对她展示“你是”信息标记，和小恶魔角色标记。\",\n    \"name\": \"红唇女郎\",\n    \"otherNight\": 20,\n    \"setup\": false,\n    \"reminders\": [],\n    \"id\": \"scarlet_womanbutton\",\n    \"edition\": \"custom\",\n    \"remindersGlobal\": [\n      \"是恶魔\"\n    ],\n    \"team\": \"minion\",\n    \"name_eng\": \"Scarlet Woman\",\n    \"firstNight\": 0,\n    \"ability\": \"如果大于等于五名玩家存活时（旅行者不计算在内）恶魔死亡，你变成那个恶魔。\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/scarlet_woman.png\"\n  },\n  {\n    \"firstNightReminder\": \"\",\n    \"otherNightReminder\": \"让诺-达鲺选择一名玩家。标记那名玩家死亡。\",\n    \"name\": \"诺-达鲺\",\n    \"otherNight\": 30,\n    \"setup\": false,\n    \"reminders\": [\n      \"死亡\",\n      \"中毒\"\n    ],\n    \"id\": \"no_dashiibutton\",\n    \"edition\": \"custom\",\n    \"team\": \"demon\",\n    \"name_eng\": \"No Dashii\",\n    \"firstNight\": 0,\n    \"ability\": \"每个夜晚*，你要选择一名玩家：他死亡。与你邻近的两名镇民中毒。\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/no_dashii.png\"\n  },\n  {\n    \"firstNightReminder\": \"\",\n    \"otherNightReminder\": \"让亡骨魔选择一名玩家。标记那名玩家死亡。如果该玩家是爪牙，标记该玩家保留能力，并标记与该玩家邻近的镇民玩家之一中毒。\",\n    \"name\": \"亡骨魔\",\n    \"otherNight\": 32,\n    \"setup\": true,\n    \"reminders\": [\n      \"死亡\",\n      \"保留能力\",\n      \"中毒\"\n    ],\n    \"id\": \"vigormortisbutton\",\n    \"edition\": \"custom\",\n    \"team\": \"demon\",\n    \"name_eng\": \"Vigormortis\",\n    \"firstNight\": 0,\n    \"ability\": \"每个夜晚*，你要选择一名玩家：他死亡。被你杀死的爪牙保留他的能力，且与他邻近的两名镇民之一中毒。[-1外来者]\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/vigormortis.png\"\n  },\n  {\n    \"firstNightReminder\": \"唤醒所有爪牙，允许他们以指向的方式决定谁照看小怪宝，但不能产生其他交流，否则会有非常糟糕的事情发生。\",\n    \"otherNightReminder\": \"唤醒所有爪牙，允许他们以指向的方式决定谁照看小怪宝，但不能产生其他交流，否则会有非常糟糕的事情发生。说书人选择一名玩家，那名玩家死亡。\",\n    \"name\": \"小怪宝\",\n    \"otherNight\": 36,\n    \"setup\": true,\n    \"reminders\": [],\n    \"id\": \"lil_monstabutton\",\n    \"edition\": \"custom\",\n    \"remindersGlobal\": [\n      \"是恶魔\",\n      \"死亡\"\n    ],\n    \"team\": \"demon\",\n    \"name_eng\": \"Lil\\u0027 Monsta\",\n    \"firstNight\": 16,\n    \"ability\": \"每个夜晚，所有爪牙要秘密决定由哪名玩家来照看小怪宝并且“是恶魔”。每个夜晚*，会有一名玩家死亡。[+1爪牙]\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/lil_monsta.png\"\n  },\n  {\n    \"firstNightReminder\": \"\",\n    \"otherNightReminder\": \"\",\n    \"name\": \"灯神\",\n    \"firstNight\": 0,\n    \"reminders\": [],\n    \"id\": \"djinnbutton\",\n    \"team\": \"fabled\",\n    \"name_eng\": \"Djinn\",\n    \"setup\": false,\n    \"ability\": \"使用灯神的相克规则。所有玩家都会知道其内容。\",\n    \"edition\": \"custom\",\n    \"image\": \"https://oss.gstonegames.com/data_file/clocktower/web/icons/djinn.png\"\n  }\n]"};
